// [Core.CDLLONGLINELookback] bars, and [BadParam] for histories of different
// lengths.
func (c *Core) CDLLONGLINEOpen(inOpen, inHigh, inLow, inClose []float64) (*CDLLONGLINEStream, int32, error) {
	sp, err := c.cdllonglineOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLLONGLINEOpenAndFill opens a stream as [Core.CDLLONGLINEOpen] does and also
// writes the outputs over the whole history, as [Core.CDLLONGLINE] writes them
// for bars 0 through len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLLONGLINELookback] values and
// share no memory with an input or another output.
//
// The errors are those of [Core.CDLLONGLINEOpen], and [BadParam] for an output
// that is empty, too short or sharing memory.
func (c *Core) CDLLONGLINEOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDLLONGLINEStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdllonglineLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdllonglineOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
